1	// Server-side quote/creation path for CUSTOM VPS + game-server specs — plain
2	// module (not "use server"), mirroring lib/order.ts / lib/game-order.ts: it does
3	// real DB reads/writes but is called FROM "use server" actions that own the
4	// session check (lib/actions-custom-plan.ts), never exported to the network
5	// directly (see lib/order.ts's serverLimitError doc for why that split matters).
6	//
7	// The pure formula/guardrail math lives in lib/custom-plan-pricing.ts (no DB, so
8	// the client-side deploy wizards can price a slider move instantly); this file
9	// wraps it with the DB-backed floor/ceiling/rate resolution and the REAL
10	// capacity check, then creates the one-off `Plan` (+ `GamePlan`, for a game
11	// order) row a custom order actually buys.
12	import { db } from "./db";
13	import { getSetting, getSettingInt } from "./settings";
14	import { extraDiskPerGbCents } from "./disk-expand";
15	import { capacityCheckRamMB, diskCapacityCheck } from "./capacity";
16	import { scheduleNode } from "./node-capacity";
17	import { GAME_GENRES, type GameFamily } from "./games";
18	import {
19	  type CustomGamePlanAnchor,
20	  type CustomPlanCeiling,
21	  type CustomPlanFloor,
22	  type CustomPlanRates,
23	  type CustomPlanSpec,
24	  CUSTOM_GAME_PLAN_DEFAULT_PER_VCPU_CENTS,
25	  CUSTOM_PLAN_DEFAULT_CEILING,
26	  CUSTOM_PLAN_DEFAULT_RATES,
27	  CUSTOM_PLAN_SORT_ORDER,
28	  computeCustomGamePlanPriceCents,
29	  computeCustomPlanPriceCents,
30	  customPlanName,
31	  customPlanSlug,
32	  gameCustomFloor,
33	  parseGameFamilyRatesOverride,
34	  validateCustomPlanSpec,
35	} from "./custom-plan-pricing";
36	
37	export { CUSTOM_PLAN_SORT_ORDER } from "./custom-plan-pricing";
38	
39	export class CustomPlanError extends Error {}
40	
41	/**
42	 * Sort-order convention already established by the ONE pre-existing manual
43	 * precedent (a "Custom 4 vCPU / 8 GB" Plan row, `sortOrder: 999, active: false`,
44	 * created before this feature existed for a one-off customer accommodation).
45	 * `sortOrder < CATALOG_SORT_ORDER_CEILING` is the live premade VPS ladder;
46	 * 900-903 are NxCloud's backing plans (also `active: false` — see prisma/schema.prisma's
47	 * comment on `Plan.nxcloudPlans`); `CUSTOM_PLAN_SORT_ORDER` (999) is reserved for
48	 * one-off custom rows. Both ranges keep `customPlanFloor` below from ever picking
49	 * up an NxCloud sizing plan or (worse) a PREVIOUS custom order's own Plan row as
50	 * "Max".
51	 */
52	const CATALOG_SORT_ORDER_CEILING = 900;
53	
54	/**
55	 * The floor every custom spec must clear: the current top-priced ACTIVE premade
56	 * VPS plan (today, Max). Read live from the DB rather than hardcoded, so a future
57	 * catalog change (a new tier added above Max) is picked up automatically with no
58	 * code change here.
59	 */
60	export async function customPlanFloor(): Promise<CustomPlanFloor> {
61	  const top = await db.plan.findFirst({
62	    where: { active: true, sortOrder: { lt: CATALOG_SORT_ORDER_CEILING } },
63	    orderBy: { priceCents: "desc" },
64	  });
65	  if (!top) throw new CustomPlanError("No base plan is configured yet — please contact support.");
66	  return {
67	    cpuCores: top.cpuCores,
68	    ramMB: top.ramMB,
69	    diskGB: top.diskGB,
70	    priceCents: top.priceCents,
71	    bandwidthTB: top.bandwidthTB,
72	  };
73	}
74	
75	/** Admin-tunable platform-wide ceiling (lib/settings.ts custom_plan_max_*). */
76	export async function customPlanCeiling(): Promise<CustomPlanCeiling> {
77	  const [maxCpuCores, maxRamGB, maxDiskGB] = await Promise.all([
78	    getSettingInt("custom_plan_max_cpu_cores", CUSTOM_PLAN_DEFAULT_CEILING.maxCpuCores),
79	    getSettingInt("custom_plan_max_ram_gb", CUSTOM_PLAN_DEFAULT_CEILING.maxRamMB / 1024),
80	    getSettingInt("custom_plan_max_disk_gb", CUSTOM_PLAN_DEFAULT_CEILING.maxDiskGB),
81	  ]);
82	  return { maxCpuCores, maxRamMB: maxRamGB * 1024, maxDiskGB };
83	}
84	
85	/** Admin-tunable per-unit rates. Disk reuses `extraDiskPerGbCents()` — the SAME
86	 *  $/GB the extra-disk upsell already charges on a premade plan — see the
87	 *  derivation comment on CUSTOM_PLAN_DEFAULT_RATES for why. */
88	export async function customPlanRates(): Promise<CustomPlanRates> {
89	  const [perVcpuCents, perRamGbCents, perDiskGbCents] = await Promise.all([
90	    getSettingInt("custom_plan_per_vcpu_cents", CUSTOM_PLAN_DEFAULT_RATES.perVcpuCents),
91	    getSettingInt("custom_plan_per_ram_gb_cents", CUSTOM_PLAN_DEFAULT_RATES.perRamGbCents),
92	    extraDiskPerGbCents(),
93	  ]);
94	  return { perVcpuCents, perRamGbCents, perDiskGbCents };
95	}
96	
97	/**
98	 * Genre-average fallback for a game family that has real `GamePlan` tiers but not
99	 * enough of them (exactly one, so a $/RAM-GB slope has no second data point to derive
100	 * from — see lib/custom-plan-pricing.ts's derivation comment). NOT hit by anything in
101	 * the live catalog today (every family with any tiers has at least 2 — see that same
102	 * comment), but a new family could plausibly launch with just one tier seeded before a
103	 * second ships, and this keeps that case priced (clearly flagged as an estimate)
104	 * instead of silently falling through to `CUSTOM_GAME_PLAN_DEFAULT_RAM_GB_CENTS`'s
105	 * `undefined` and gating the family for a reason that isn't actually "we have zero
106	 * data" — we have a real anchor tier, just not a real slope.
107	 *
108	 * Averages the derived (non-estimated) rates of every OTHER family that shares at
109	 * least one genre tag (lib/games.ts GAME_GENRES) with this one; a family with no genre
110	 * tag, or no genre-mates in the table, falls back to the average of the WHOLE table —
111	 * still grounded in real derived data, just not narrowed by genre. Never fabricated
112	 * from nothing: this only ever runs for a family that already has one real tier
113	 * anchoring its base price, and only picks the SLOPE from other real games' data.
114	 */
115	export function estimatedGameFamilyRamRateCents(
116	  family: string,
117	  ramRatesCents: Record<string, number>,
118	): { cents: number; estimated: true; basis: string } {
119	  const genres = GAME_GENRES[family as GameFamily];
120	  const allRates = Object.entries(ramRatesCents).filter(([f]) => f !== family);
121	  const genreMates = genres?.length
122	    ? allRates.filter(([f]) => GAME_GENRES[f as GameFamily]?.some((g) => genres.includes(g)))
123	    : [];
124	  const pool = genreMates.length ? genreMates : allRates;
125	  const avg = pool.reduce((s, [, c]) => s + c, 0) / (pool.length || 1);
126	  return {
127	    cents: Math.round(avg),
128	    estimated: true,
129	    basis: genreMates.length
130	      ? `genre average (${genreMates.length} family/families sharing ${genres!.join("/")})`
131	      : "platform-wide average across all derived game families",
132	  };
133	}
134	
135	/**
136	 * The admin-tunable GAME rate SETTINGS, loaded once: the shared per-vCPU rate
137	 * (`custom_plan_game_per_vcpu_cents`), the per-family RAM-GB override table
138	 * (`custom_plan_game_ram_rates_json`, merged over CUSTOM_GAME_PLAN_DEFAULT_RAM_GB_CENTS
139	 * — see lib/custom-plan-pricing.ts), and disk (`extraDiskPerGbCents()`, shared with
140	 * VPS). Split out from `customGamePlanRates` below so a caller resolving MANY
141	 * families in one request (the deploy wizard's page loader builds a `CustomPlanConfig`
142	 * per game family) reads these 2 settings ONCE rather than once per family.
143	 */
144	export async function loadGameRateSettings(): Promise<{
145	  perVcpuCents: number;
146	  ramRatesCents: Record<string, number>;
147	  perDiskGbCents: number;
148	}> {
149	  const [perVcpuCents, ramRatesJson, perDiskGbCents] = await Promise.all([
150	    getSettingInt("custom_plan_game_per_vcpu_cents", CUSTOM_GAME_PLAN_DEFAULT_PER_VCPU_CENTS),
151	    getSetting("custom_plan_game_ram_rates_json", ""),
152	    extraDiskPerGbCents(),
153	  ]);
154	  return { perVcpuCents, ramRatesCents: parseGameFamilyRatesOverride(ramRatesJson), perDiskGbCents };
155	}
156	
157	/**
158	 * Pure: resolve ONE family's rates from already-loaded settings (`loadGameRateSettings`).
159	 * Always resolves to SOME rate once a family has at least one real tier to anchor
160	 * from — the "we truly have nothing" case (zero tiers at all) is caught earlier, by
161	 * checking for a top tier before this is ever called.
162	 */
163	export function resolveGameFamilyRates(
164	  gameFamily: string,
165	  settings: { perVcpuCents: number; ramRatesCents: Record<string, number>; perDiskGbCents: number },
166	): { rates: CustomPlanRates; estimated: boolean; basis?: string } {
167	  const direct = settings.ramRatesCents[gameFamily];
168	  if (direct !== undefined) {
169	    return {
170	      rates: { perVcpuCents: settings.perVcpuCents, perRamGbCents: direct, perDiskGbCents: settings.perDiskGbCents },
171	      estimated: false,
172	    };
173	  }
174	  const est = estimatedGameFamilyRamRateCents(gameFamily, settings.ramRatesCents);
175	  return {
176	    rates: { perVcpuCents: settings.perVcpuCents, perRamGbCents: est.cents, perDiskGbCents: settings.perDiskGbCents },
177	    estimated: true,
178	    basis: est.basis,
179	  };
180	}
181	
182	/** `loadGameRateSettings` + `resolveGameFamilyRates` for a single family — the
183	 *  convenient one-shot form for a caller (`customGamePlanQuote` below) that only
184	 *  ever needs one family per call. */
185	export async function customGamePlanRates(
186	  gameFamily: string,
187	): Promise<{ rates: CustomPlanRates; estimated: boolean; basis?: string }> {
188	  return resolveGameFamilyRates(gameFamily, await loadGameRateSettings());
189	}
190	
191	export type CustomPlanQuote =
192	  | { ok: true; floor: CustomPlanFloor; ceiling: CustomPlanCeiling; rates: CustomPlanRates; priceCents: number }
193	  | { ok: false; reason: string; floor: CustomPlanFloor; ceiling: CustomPlanCeiling };
194	
195	/** Validate + price a custom spec without creating anything. Never throws — a bad
196	 *  spec comes back `{ ok: false, reason }` so the wizard can show it inline. */
197	export async function customPlanQuote(spec: CustomPlanSpec): Promise<CustomPlanQuote> {
198	  const [floor, ceiling, rates] = await Promise.all([customPlanFloor(), customPlanCeiling(), customPlanRates()]);
199	  const v = validateCustomPlanSpec(spec, floor, ceiling);
200	  if (!v.ok) return { ok: false, reason: v.reason, floor, ceiling };
201	  const priceCents = computeCustomPlanPriceCents(spec, floor, rates);
202	  return { ok: true, floor, ceiling, rates, priceCents };
203	}
204	
205	/**
206	 * The game analogue of `customPlanQuote` — same "never throws, {ok:false, reason}
207	 * on a bad spec" contract, but family-aware throughout: floor is
208	 * `gameCustomFloor` (widened per-family), rates are this family's own derived
209	 * rate, and price is `computeCustomGamePlanPriceCents` (extends the family's own
210	 * top tier, not the flat VPS Max price). This is what the deploy wizard's
211	 * "Build a custom X server" panel calls for BOTH its instant slider preview
212	 * bounds/rate display AND its debounced "authoritative" price/capacity check —
213	 * before this existed, the game builder silently reused the VPS-only
214	 * `quoteCustomPlanAction`, so a customer saw the WRONG (flat VPS) price while
215	 * sliding and only got the correct family-rate price after clicking through to
216	 * `confirmCustomGamePlanAction` — a real quote-vs-charge mismatch in the UI even
217	 * though what actually got charged was already correct. Fixed alongside the
218	 * create-path fix rather than left for later, since it is the same bug class
219	 * this whole change exists to close.
220	 *
221	 * `createCustomGamePlan` below calls this too (mirroring how `createCustomPlan`
222	 * calls `customPlanQuote`) so there is exactly one place this math lives.
223	 */
224	export async function customGamePlanQuote(
225	  gameFamily: string,
226	  spec: CustomPlanSpec,
227	): Promise<CustomPlanQuote> {
228	  const [topTier, vpsFloor, ceiling] = await Promise.all([
229	    db.gamePlan.findFirst({
230	      where: { gameFamily, active: true, sortOrder: { lt: CATALOG_SORT_ORDER_CEILING } },
231	      orderBy: { priceCents: "desc" },
232	    }),
233	    customPlanFloor(),
234	    customPlanCeiling(),
235	  ]);
236	  if (!topTier) {
237	    return {
238	      ok: false,
239	      reason: "Custom-sized servers for this game aren't available yet — there's no pricing catalog to build a custom quote from. Please contact support.",
240	      floor: vpsFloor,
241	      ceiling,
242	    };
243	  }
244	  const anchor: CustomGamePlanAnchor = {
245	    cpuCores: topTier.cpuCores,
246	    ramMB: topTier.ramMB,
247	    diskGB: topTier.diskGB,
248	    priceCents: topTier.priceCents,
249	  };
250	  const floor = gameCustomFloor(vpsFloor, anchor);
251	  const v = validateCustomPlanSpec(spec, floor, ceiling);
252	  if (!v.ok) return { ok: false, reason: v.reason, floor, ceiling };
253	
254	  const gameRates = await customGamePlanRates(gameFamily);
255	  if (gameRates.estimated) {
256	    // Should never fire against the live catalog as of 2026-09-29 — see
257	    // estimatedGameFamilyRamRateCents's own comment. Logged here (not just in
258	    // createCustomGamePlan) so an admin notices the moment a QUOTE, not only a
259	    // real order, starts leaning on a genre-average guess.
260	    console.warn(`[custom-plan] ${gameFamily} quoted with an ESTIMATED RAM rate (${gameRates.basis})`);
261	  }
262	  const priceCents = computeCustomGamePlanPriceCents(spec, anchor, gameRates.rates, vpsFloor.priceCents);
263	  return { ok: true, floor, ceiling, rates: gameRates.rates, priceCents };
264	}
265	
266	/**
267	 * The REAL, pre-checkout capacity check — reuses the exact oversell guards
268	 * lib/order.ts placeOrder / lib/game-order.ts placeGameOrder already run for
269	 * every premade-plan order (capacityCheckRamMB mirrors capacityCheck;
270	 * diskCapacityCheck is the identical function). A custom spec can ask for more
271	 * RAM than ANY catalog plan, so it must be screened the same way — this is not
272	 * a second, weaker guard, it's the same one with a raw RAM/disk number instead
273	 * of a `Plan` row backing it.
274	 */
275	export async function customPlanCapacityCheck(spec: CustomPlanSpec): Promise<{ ok: boolean; reason?: string }> {
276	  const ramOk = await capacityCheckRamMB(spec.ramMB);
277	  if (!ramOk.ok) return ramOk;
278	  // Which node WOULD take this — same scheduler VPS/game orders use — so the disk
279	  // check below runs against a real candidate node's pool, not "any node".
280	  const node = await scheduleNode(spec.ramMB);
281	  if (!node) {
282	    return { ok: false, reason: "No node currently has room for a server this size. Please contact support." };
283	  }
284	  return diskCapacityCheck(node.id, spec.diskGB);
285	}
286	
287	/** 6-char alnum suffix — matches the one pre-existing manual precedent's slug
288	 *  shape ("custom-4c8g-hmcebh"). */
289	function randSuffix(n = 6): string {
290	  return Math.random().toString(36).slice(2, 2 + n);
291	}
292	
293	export type CreatedCustomPlan = {
294	  id: string;
295	  name: string;
296	  cpuCores: number;
297	  ramMB: number;
298	  diskGB: number;
299	  bandwidthTB: number;
300	  priceCents: number;
301	  storageTier: string;
302	};
303	
304	/**
305	 * Create ONE real `Plan` row for an exact spec+price — the same manual-accommodation
306	 * pattern already proven in production once (see the sort-order doc comment above),
307	 * now automated. Shared by `createCustomPlan` (VPS) and `createCustomGamePlan`
308	 * (game) below — the retry-on-slug-collision loop and row shape are identical, only
309	 * how `priceCents` gets computed differs between the two callers.
310	 *
311	 * Created INACTIVE with `sortOrder: 999` so it NEVER appears in any catalog query
312	 * (every page that lists plans filters `active: true` — see
313	 * app/dashboard/deploy/page.tsx) — it exists solely to be the ONE plan this ONE
314	 * order's Server row points at. From here on, every downstream money path
315	 * (lib/order.ts orderQuote/placeOrder, lib/resize.ts, lib/renewal-charge.ts,
316	 * lib/capacity.ts, admin displays) reads straight off the `Plan` relation exactly
317	 * like it does for a premade plan — no special-casing needed anywhere else.
318	 */
319	async function createCustomPlanRow(
320	  spec: CustomPlanSpec,
321	  priceCents: number,
322	  bandwidthTB: number,
323	): Promise<CreatedCustomPlan> {
324	  let lastErr: unknown;
325	  for (let attempt = 0; attempt < 3; attempt++) {
326	    try {
327	      const plan = await db.plan.create({
328	        data: {
329	          slug: customPlanSlug(spec, randSuffix()),
330	          name: customPlanName(spec),
331	          cpuCores: spec.cpuCores,
332	          ramMB: spec.ramMB,
333	          diskGB: spec.diskGB,
334	          bandwidthTB,
335	          priceCents,
336	          storageTier: "nvme",
337	          active: false,
338	          sortOrder: CUSTOM_PLAN_SORT_ORDER,
339	        },
340	      });
341	      return {
342	        id: plan.id,
343	        name: plan.name,
344	        cpuCores: plan.cpuCores,
345	        ramMB: plan.ramMB,
346	        diskGB: plan.diskGB,
347	        bandwidthTB: plan.bandwidthTB,
348	        priceCents: plan.priceCents,
349	        storageTier: plan.storageTier,
350	      };
351	    } catch (e) {
352	      lastErr = e; // near-impossible slug collision (6-char random suffix) — retry once or twice
353	    }
354	  }
355	  throw lastErr instanceof Error ? lastErr : new CustomPlanError("Could not create the custom plan — please try again.");
356	}
357	
358	/**
359	 * Re-validates guardrails AND capacity from scratch (a client-supplied price/spec is
360	 * never trusted for money — mirrors every other quote→place split in this codebase)
361	 * before writing anything, then hands off to `createCustomPlanRow`.
362	 */
363	export async function createCustomPlan(spec: CustomPlanSpec): Promise<CreatedCustomPlan> {
364	  const quote = await customPlanQuote(spec);
365	  if (!quote.ok) throw new CustomPlanError(quote.reason);
366	  const cap = await customPlanCapacityCheck(spec);
367	  if (!cap.ok) throw new CustomPlanError(cap.reason ?? "Not enough room for that configuration right now.");
368	  return createCustomPlanRow(spec, quote.priceCents, quote.floor.bandwidthTB);
369	}
370	
371	export type CreatedCustomGamePlan = {
372	  plan: CreatedCustomPlan;
373	  gamePlanId: string;
374	  name: string;
375	  priceCents: number;
376	  slots: number | null;
377	};
378	
379	/**
380	 * Game analogue of `createCustomPlan`: also creates the `GamePlan` tier that rides on
381	 * top of the freshly-created base `Plan`, exactly like every premade game tier
382	 * already does (`GamePlan.basePlanId`) — see prisma/seed-gameplans.ts.
383	 *
384	 * REAL per-family pricing (2026-09-29, replacing the stop-gap throw that blocked
385	 * every custom game order — see docs/DOCUMENTATION.md). Unlike `createCustomPlan`,
386	 * the price here is NOT floor.priceCents + flat-VPS-rate * extra: it's this game
387	 * family's own top real `GamePlan` tier's price, extended by that family's own
388	 * per-vCPU/per-RAM-GB rate (lib/custom-plan-pricing.ts's
389	 * `computeCustomGamePlanPriceCents` — read its derivation comment for the full
390	 * methodology) — so a custom build is a genuine continuation of THIS game's own
391	 * pricing curve, not the platform's generic VPS curve wearing a game's name. The
392	 * floor a spec must clear is similarly widened per-family (`gameCustomFloor`) so a
393	 * "custom" order can never be smaller, on any dimension, than this family's own
394	 * biggest premade tier.
395	 *
396	 * Still gated (throws) for a family with ZERO live tiers to anchor from at all —
397	 * see `customGamePlanRates`'s doc and lib/custom-plan-pricing.ts's derivation
398	 * comment for exactly which families that is and why (as of 2026-09-29:
399	 * `schedule1` and the four `plutonium*` variants — none of which can be bought as a
400	 * premade tier either today, so this changes nothing about their sellability).
401	 */
402	export async function createCustomGamePlan(opts: {
403	  spec: CustomPlanSpec;
404	  gameFamily: string;
405	  players?: number | null;
406	}): Promise<CreatedCustomGamePlan> {
407	  // Same quote→place split every other money path in this codebase uses (see
408	  // createCustomPlan/customPlanQuote above) — one function computes the price,
409	  // both the read-only quote (customGamePlanQuote, called by the wizard while a
410	  // customer is still moving sliders) and this real write path call it, so they
411	  // can never independently drift from each other.
412	  const quote = await customGamePlanQuote(opts.gameFamily, opts.spec);
413	  if (!quote.ok) throw new CustomPlanError(quote.reason);
414	  const cap = await customPlanCapacityCheck(opts.spec);
415	  if (!cap.ok) throw new CustomPlanError(cap.reason ?? "Not enough room for that configuration right now.");
416	
417	  const plan = await createCustomPlanRow(opts.spec, quote.priceCents, quote.floor.bandwidthTB);
418	  const gp = await db.gamePlan.create({
419	    data: {
420	      gameFamily: opts.gameFamily,
421	      name: `${customPlanName(opts.spec)} (${opts.gameFamily})`,
422	      ramMB: plan.ramMB,
423	      cpuCores: plan.cpuCores,
424	      diskGB: plan.diskGB,
425	      slots: opts.players ?? null,
426	      priceCents: plan.priceCents,
427	      termMonths: 1,
428	      basePlanId: plan.id,
429	      active: false,
430	      sortOrder: CUSTOM_PLAN_SORT_ORDER,
431	    },
432	  });
433	  return { plan, gamePlanId: gp.id, name: gp.name, priceCents: gp.priceCents, slots: gp.slots };
434	}
