1	"use server";
2	
3	// "use server" surface for the custom-plan builder — every export here is a
4	// public network endpoint the moment it exists, so EVERY one starts with its own
5	// `requireUser()` (see lib/order.ts serverLimitError's doc for exactly why a
6	// helper that skips this is a HAZARD test/auth-lockouts.test.ts exists to catch).
7	//
8	// This module owns no money movement: `confirmCustomPlanAction` /
9	// `confirmCustomGamePlanAction` only create the one-off catalog row (a real
10	// `Plan`/`GamePlan`, see lib/custom-plan.ts) the customer then buys through the
11	// EXACT same `payAndDeploy` / `payAndDeployGame` path every premade plan uses —
12	// so the actual charge, capacity re-check, wallet debit and invoice are all
13	// handled by code this feature does not touch at all.
14	import { z } from "zod";
15	import { requireUser, assertNotImpersonating } from "./auth";
16	import { GAME_FAMILIES } from "./games";
17	import { annualDiscountPct } from "./annual-discount";
18	import { VPS_TERMS, vpsEffectiveMonthly } from "./billing-terms";
19	import {
20	  CustomPlanError,
21	  createCustomGamePlan,
22	  createCustomPlan,
23	  customGamePlanQuote,
24	  customPlanCapacityCheck,
25	  customPlanQuote,
26	} from "./custom-plan";
27	
28	const specSchema = z.object({
29	  cpuCores: z.coerce.number().int().min(1).max(4096),
30	  ramMB: z.coerce.number().int().min(1).max(8 * 1024 * 1024),
31	  diskGB: z.coerce.number().int().min(1).max(1_000_000),
32	});
33	
34	export type CustomPlanQuoteResult = {
35	  ok: boolean;
36	  error?: string;
37	  priceCents?: number;
38	  floor?: { cpuCores: number; ramMB: number; diskGB: number; priceCents: number };
39	  ceiling?: { maxCpuCores: number; maxRamMB: number; maxDiskGB: number };
40	  capacityOk?: boolean;
41	  capacityReason?: string;
42	  /** Effective per-month rate at each billing term (1/12/24/36), worked out
43	   *  HERE through `vpsEffectiveMonthly` — the same term formula (and the same
44	   *  live admin annual-discount setting) orderQuote / gameOrderQuote charge
45	   *  through — so the Nexion wizard's custom card can print a term price
46	   *  without multiplying anything in the browser. */
47	  termMonthlyCents?: Record<number, number>;
48	};
49	
50	/** Server-side per-term effective monthly rates for a custom monthly price. */
51	async function termMonthlyMatrix(monthlyCents: number): Promise<Record<number, number>> {
52	  const pct = await annualDiscountPct();
