68	/** Cheapest real custom build: one unit over the floor on the cheapest
69	 *  dimension — through the same formula (`previewPriceCents`, VPS or game as
70	 *  `cfg` dictates), so "from $X" is never a guess. */
71	function minCustomPriceCents(cfg: CustomPlanConfig | GameCustomPlanConfig): number {
72	  const f = cfg.floor;
73	  const base = { cpuCores: f.cpuCores, ramMB: f.ramMB, diskGB: f.diskGB };
74	  return Math.min(
75	    previewPriceCents({ ...base, cpuCores: base.cpuCores + 1 }, cfg),
76	    previewPriceCents({ ...base, ramMB: base.ramMB + 1024 }, cfg),
77	    previewPriceCents({ ...base, diskGB: base.diskGB + DISK_STEP_GB }, cfg),
78	  );
79	}
