267	export function CustomServerBuilder({ cfg, kind, family, familyName, checkoutFields, terms, onBuilt, onClose }: {
268	  cfg: CustomPlanConfig | GameCustomPlanConfig;
269	  kind: "vps" | "game";
270	  /** Game orders only. */
271	  family?: string;
272	  familyName?: string;
273	  checkoutFields?: ConfigField[];
274	  terms: TermOption[];
275	  /** Called after the custom row exists and has been selected. */
276	  onBuilt: () => void;
277	  onClose: () => void;
278	}) {
279	  const { o, cat, applyCustomPlan, applyCustomTier } = useOrder();
280	  const money = useMoney();
281	  const { floor, ceiling, rates } = cfg;
282	  const isGame = kind === "game" && !!family;
283	
284	  // Start from the build already made this session, if there is one, so
285	  // "Edit custom build" reopens on what the customer chose — not a reset.
286	  const existing: (PlanOption | GameTier) | null = isGame
287	    ? cat.games.find((g) => g.family === family)?.tiers.find((t) => t.custom) ?? null
288	    : cat.plans.find((p) => p.custom) ?? null;
289	
290	  const engineMax = isGame ? engineMaxPlayers(checkoutFields) : null;
291	  const sliderMax = isGame
292	    ? Math.max(2, Math.min(playerSliderMax(family as GameFamily), engineMax ?? Infinity))
293	    : 0;
294	
295	  /* Round a recommendation onto the sliders' own grid (whole GB of RAM, 10 GB
296	     of disk above the floor) and clamp into floor..ceiling. If that lands on
297	     the floor exactly — i.e. the headcount fits a standard plan — nudge RAM up
298	     1 GB so the spec is a real custom build (a floor-identical spec is just
299	     "Max" and the server rightly refuses it). */
300	  const fromPlayers = (players: number): { spec: CustomPlanSpec; overCeiling: boolean; fitsStandard: boolean } => {
301	    const rec = recommendedSpecForPlayers(family as GameFamily, players);
302	    const raw: CustomPlanSpec = {
303	      cpuCores: rec.cpuCores,
304	      ramMB: Math.ceil(rec.ramMB / 1024) * 1024,
305	      diskGB: floor.diskGB + Math.ceil(Math.max(0, rec.diskGB - floor.diskGB) / DISK_STEP_GB) * DISK_STEP_GB,
306	    };
