219	/**
220	 * Parse a sold price back off Stripe metadata. Returns null unless EVERY field is
221	 * well-formed: a half-parsed price would be worse than no price at all, because
222	 * the caller's fallback (re-quote) is at least internally consistent.
223	 */
224	export function parseOrderPrice(raw: unknown): OrderPrice | null {
225	  let obj: unknown = raw;
226	  if (typeof raw === "string") {
227	    try {
228	      obj = JSON.parse(raw);
229	    } catch {
230	      return null;
231	    }
232	  }
233	  if (!obj || typeof obj !== "object") return null;
234	  const { chargeCents, promoPercent, promoName, taxCents, taxRatePercent, taxCountry } =
235	    obj as Record<string, unknown>;
236	  if (typeof chargeCents !== "number" || !Number.isInteger(chargeCents) || chargeCents < 0) return null;
237	  if (typeof promoPercent !== "number" || !Number.isInteger(promoPercent)) return null;
238	  if (promoPercent < 0 || promoPercent > 100) return null;
239	  // Tax fields are ADDITIVE and lenient: a session written before Finding 1 (or with a
240	  // malformed tax field) carries none, and the charge path recomputes tax from the
241	  // owner's country — which undertaxes at worst, never overcharges.
242	  const tc = typeof taxCents === "number" && Number.isInteger(taxCents) && taxCents >= 0 ? taxCents : 0;
243	  const tr =
244	    typeof taxRatePercent === "number" && Number.isFinite(taxRatePercent) && taxRatePercent >= 0
245	      ? taxRatePercent
246	      : 0;
247	  return {
248	    chargeCents,
249	    promoPercent,
250	    promoName: typeof promoName === "string" ? promoName : "",
251	    taxCents: tc,
252	    taxRatePercent: tr,
253	    taxCountry: typeof taxCountry === "string" ? taxCountry : "",
254	  };
255	}
