257	/** Extract a plain OrderIntent from a deploy form. */
258	export function intentFromFormData(formData: FormData): OrderIntent {
259	  return {
260	    planId: String(formData.get("planId") ?? ""),
261	    osTemplateId: String(formData.get("osTemplateId") ?? ""),
262	    hostname: String(formData.get("hostname") ?? ""),
263	    nodeId: String(formData.get("nodeId") ?? "") || undefined,
264	    region: String(formData.get("region") ?? "") || undefined,
265	    provider: (String(formData.get("provider") ?? "") || undefined) as OrderIntent["provider"],
266	    addonMalware: formData.get("addon_malware") === "1",
267	    addonBackup: formData.get("addon_backup") === "1",
268	    addonDocker: formData.get("addon_docker") === "1",
269	    termMonths: Number(formData.get("termMonths") ?? 1),
270	    dedicatedIp: formData.get("dedicatedIp") === "1",
271	    sshPublicKey: String(formData.get("sshPublicKey") ?? "").trim() || undefined,
272	    sshKeyName: String(formData.get("sshKeyName") ?? "deploy-key").slice(0, 60),
273	    free: formData.get("free") === "1",
274	    // Rounded DOWN to a purchasable step — a malformed value can only ever cost
275	    // the customer less, never more. Left UNDEFINED (not 0) when nothing was
276	    // bought so it drops out of JSON.stringify: the intent is round-tripped
277	    // through Stripe metadata, which is capped at 500 chars (lib/stripe.ts
278	    // createOrderCheckout), and every byte of headroom matters there.
279	    extraDiskGB: normalizeExtraDiskGB(formData.get("extraDiskGB")) || undefined,
280	    couponCode: String(formData.get("couponCode") ?? "").trim().toUpperCase() || undefined,
281	    // Only PLUS is a paid choice; left UNDEFINED for FREE (the included tier) so it
282	    // drops out of the Stripe-metadata JSON round-trip, like extraDiskGB. orderQuote
283	    // re-normalizes undefined back to FREE.
284	    backupTier: normalizeBackupTier(formData.get("backup_tier")) === "PLUS" ? "PLUS" : undefined,
285	  };
286	}
