288	/**
289	 * Pick the least-committed enabled node (RAM headroom), while steering AWAY from
290	 * a node this order would push to/past the CRITICAL capacity threshold when
291	 * another node has room. Falls back to primary (any node) when every candidate is
292	 * already critical — the scheduler never REFUSES an order for a capacity warning
293	 * (that's the node-capacity alert's job, lib/node-capacity.ts); it only prefers a
294	 * roomier node when one exists. DB-only so order placement never blocks on a
295	 * Proxmox round trip.
296	 */
297	/** Validate + price an order without placing it. Throws OrderError on any problem. */
298	export async function orderQuote(
299	  intent: OrderIntent,
300	  opts?: {
301	    suppressPromo?: boolean;
302	    /**
303	     * CREATOR PARTNER PROGRAM (2026-09-26): the customer placing/previewing this
304	     * order, so the quote can fold in their 50%-off-first-purchase /
305	     * 10%-off-every-purchase-after discount. OPTIONAL — every existing call site
306	     * that doesn't pass it keeps quoting at exactly today's price (0% partner
307	     * discount), byte-for-byte. VPS is never a domain, so this always resolves
308	     * through the non-domain path.
309	     */
310	    userId?: string;
311	  },
312	) {
313	  const parsed = orderSchema.safeParse(intent);
314	  if (!parsed.success) throw new OrderError(parsed.error.issues[0]?.message ?? "Invalid input.");
315	  const plan = await db.plan.findUnique({ where: { id: intent.planId } });
316	  const os = await db.osTemplate.findUnique({ where: { id: intent.osTemplateId } });
317	  // A ONE-OFF CUSTOM plan (lib/custom-plan.ts createCustomPlan, "build a custom
318	  // server") is deliberately created `active: false` — every plain
319	  // `where: { active: true }` catalog/resize-picker/marketing query in this
320	  // codebase (30+ call sites, none scoped to a single order or customer) must
321	  // never surface it as a generically pickable tile. But it must still be a
322	  // valid target for the ONE order that just built it, so `sortOrder` — the
323	  // existing marker reserved for exactly this row shape — is accepted here as an
324	  // alternative to `active`. No other code path needs this carve-out: renewals
325	  // (lib/renewal-charge.ts) never check `active` at all, and the resize-target
326	  // picker's own `where: { active: true }` query correctly keeps a custom plan
327	  // out of every OTHER customer's upgrade options with no change needed there.
328	  const planPurchasable = !!plan?.active || plan?.sortOrder === CUSTOM_PLAN_SORT_ORDER;
329	  if (!planPurchasable || !os?.active) throw new OrderError("Plan or OS not available.");
330	  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
331	    throw new OrderError(
332	      `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
333	    );
334	  }
335	  const term = vpsTerm(Number(intent.termMonths ?? 1));
336	  // The admin-configured ANNUAL discount, resolved ONCE here and passed to
337	  // `vpsTermPriceCents` so the annual term is charged at the same rate the deploy
338	  // wizard displayed and every renewal will bill. Ignored for non-annual terms.
339	  const annualPct = await annualDiscountPct();
340	  const ipCents = intent.dedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0;
341	
342	  // Extra root disk, priced per GB/month and multiplied over the term exactly
343	  // like the dedicated-IP add-on (and, like it, NOT discounted by the term or the
344	  // promo — the customer pays the same $/GB whichever term they pick, and renews
345	  // at the same rate). Growth is one-way: this is permanent for the server.
346	  const extraDiskGB = normalizeExtraDiskGB(intent.extraDiskGB);
347	  const extraDiskPerGb = extraDiskGB > 0 ? await extraDiskPerGbCents() : 0;
348	  const extraDiskMonthlyCents = extraDiskCentsAt(extraDiskGB, extraDiskPerGb);
349	  const extraDiskCents = extraDiskMonthlyCents * term.months;
350	  if (effectiveDiskGB(plan.diskGB, extraDiskGB) > EXTRA_DISK_MAX_TOTAL_GB) {
351	    throw new OrderError(`A server's disk tops out at ${EXTRA_DISK_MAX_TOTAL_GB} GB.`);
352	  }
353	
354	  // Paid backup RETENTION tier, priced per month and multiplied over the term
355	  // exactly like the extra-disk add-on (NOT promo-discounted — the customer pays
356	  // the same $/mo whichever term or promo, and renews at the same rate through
357	  // renewalCharge). Only PLUS is paid; FREE (the included tier) is $0.
358	  const backupTier = normalizeBackupTier(intent.backupTier);
359	  const backupMonthlyCents =
360	    backupTier === "FREE" ? 0 : backupTierMonthlyCents(backupTier, await backupPlusMonthlyCents());
361	  const backupCents = backupMonthlyCents * term.months;
362	
363	  // Seasonal promo = HONEST intro discount on the plan's FIRST-term charge only.
364	  // The regular term price (vpsTermPriceCents) is what renewals bill unchanged in
365	  // worker/billing.ts — so the strikethrough shown on the marketing pages is the
366	  // real renewal price and this discounted value is the real first-term price.
367	  // Marketing displays promoPriceCents(regular) too, so displayed === charged.
368	  // (Dedicated IP is billed at full price; the promo only touches the plan.)
369	  const regularPlanCents = vpsTermPriceCents(plan.priceCents, term.months, annualPct);
370	
371	  // LOW intro price → RENEWS at regular. A per-plan `introPriceCents` (set by an
372	  // admin) makes the FIRST term cheaper and leaves every renewal at the regular
373	  // `priceCents` — renewal code never reads the intro column, so renewal === regular
374	  // by construction (lib/renewal-charge.ts). Modelled as a first-term REDUCTION of
375	  // the regular term total (not a second price), so the regular term stays the one
376	  // basis renewals bill and proration prices against. `introDiscountCents` is 0 for
377	  // every plan without an intro price, so the whole VPS flow below is unchanged for
378	  // them. VPS never carries the first-month-free promo (`firstMonthFreeAppliesTo`),
379	  // so intro and FMF never stack here.
380	  const introMonthlyCents = planIntroMonthlyCents(plan);
381	  const introTermMonths = planIntroTermMonths(plan);
382	  const introDiscountCents = introFirstTermDiscountCents(
383	    plan.priceCents,
384	    introMonthlyCents,
385	    term.months,
386	    introTermMonths,
387	    annualPct,
388	  );
389	  // The plan-portion cash the FIRST term is sold at, intro applied. Renewals ignore it.
390	  const introFirstTermPlanCents = Math.max(0, regularPlanCents - introDiscountCents);
391	  // The rate this first term is sold at (percent off the regular term total) — stamped
392	  // on Server.termPromoPercent below via the promo object so proration/refunds price
393	  // against it exactly like a seasonal promo.
394	  const introPercent = introSoldPercent(regularPlanCents, introDiscountCents);
395	  const introRenewalMonthly = plan.priceCents; // what the "then $X/mo" copy quotes
396	  // When a plan has an intro price we present it THROUGH the same `promo` channel the
397	  // seasonal-sale plumbing uses (name + percent travel on OrderPrice and stamp
398	  // termPromoPercent). `firstMonthFree: false` keeps it out of the one-month-free
399	  // redemption machinery — an intro price has no per-account cap; it is simply this
400	  // plan's first-term price.
401	  const promo =
402	    introDiscountCents > 0
403	      ? {
404	          id: "intro-price",
405	          name: `Intro price — renews at $${(introRenewalMonthly / 100).toFixed(2)}/mo`,
406	          label: "Intro price",
407	          discountPercent: introPercent,
408	          firstMonthFree: false,
409	        }
410	      : currentPromo(new Date());
411	  // The promo is now MANAGED: the owner can switch it off, and every claim is
412	  // capped 1/account + 1/IP (lib/promo-redemption.ts). When the toggle is off the
413	  // quote shows — and placeOrder charges — the full price, so display === charged
414	  // on the disabled path. When it is on, the quote shows the first-month-free
415	  // price and the atomic claim in placeOrder's tx is the final arbiter of whether
416	  // the credit is actually granted (a lost race there is charged full).
417	  // `suppressPromo` prices this quote at FULL price even when the promo is on —
418	  // the card path uses it to re-quote for a customer who has already redeemed
419	  // (per-account/IP), so their Stripe leg and stamped total are full, not free.
420	  // The first-month-free promo is scoped to Shared Web Hosting only — VPS always
421	  // bills full. `firstMonthFreeAppliesTo("VPS")` is false, so promoEnabled is
422	  // false here and planFirstTermCents falls through to the regular term total.
423	  const promoEnabled =
424	    firstMonthFreeAppliesTo("VPS") && !opts?.suppressPromo && (await firstMonthFreeEnabled());
425	  // First-month-free must credit exactly ONE MONTH — not zero a multi-month term.
426	  // A naive promoPriceCents(termTotal) at 100% off would give a 36-month term 3
427	  // YEARS free. So we subtract one month of the plan's rate from the term total.
428	  // For a 1-month term this lands at $0 (genuinely first month free); for a 12/24/
429	  // 36-month term the customer pays the term minus one month. Renewals bill the
430	  // full vpsTermPriceCents unchanged (worker/billing.ts) — displayed === charged.
431	  const planFirstTermCents =
432	    promoEnabled && promo.firstMonthFree
433	      ? Math.max(0, regularPlanCents - plan.priceCents)
434	      : regularPlanCents;
435	  // The one-month credit this order gets IF the atomic claim succeeds. 0 when the
436	  // promo is off. placeOrder adds it back to charge full when the claim is lost.
437	  const promoCreditCents = regularPlanCents - planFirstTermCents;
438	
439	  // Optional checkout coupon: a service-locked, term-capped discount on the PLAN
440	  // portion only (not the dedicated-IP or extra-disk add-ons). Never throws for a
441	  // bad code — an invalid coupon leaves the price at full and surfaces `couponError`
442	  // so the deploy preview can show it; the redemption itself (count + per-user +
443	  // per-IP guards) is claimed atomically in placeOrder.
444	  let couponId: string | null = null;
445	  let couponDiscountCents = 0;
446	  let couponLabel = "";
447	  let couponError = "";
448	  let couponMaxRedemptions: number | null = null;
449	  let couponFirstTimeOnly = false;
450	  let couponExcludeActiveCustomers = false;
451	  let couponTrialDays: number | null = null;
452	  const code = (intent.couponCode ?? "").trim().toUpperCase();
453	  if (code) {
454	    if (!(await getSettingBool("coupons_enabled", true))) {
455	      couponError = "Promo codes are currently disabled.";
456	    } else {
457	      const coupon = await db.coupon.findUnique({ where: { code } });
458	      if (!coupon) {
459	        couponError = "That code isn’t valid.";
460	      } else {
461	        const verdict = couponOrderDiscountCents(
462	          {
463	            kind: coupon.kind,
464	            value: coupon.value,
465	            serviceKind: coupon.serviceKind,
466	            planSlug: coupon.planSlug,
467	            maxTermMonths: coupon.maxTermMonths,
468	            active: coupon.active,
469	            expiresAt: coupon.expiresAt,
470	            maxRedemptions: coupon.maxRedemptions,
471	            timesRedeemed: coupon.timesRedeemed,
472	            minAmountCents: coupon.minAmountCents,
473	          },
474	          {
475	            serviceKind: "VPS",
476	            planSlug: plan.slug,
477	            planMonthlyCents: plan.priceCents,
478	            termMonths: term.months,
479	            // Coupon discounts the intro-reduced plan portion, so an intro price and a
480	            // coupon cannot together drive the plan charge below zero, and a percentage
481	            // coupon is honestly "% off what you actually pay this term".
482	            planChargeCents: introFirstTermPlanCents,
483	          },
484	          new Date(),
485	        );
486	        if (verdict.ok) {
487	          couponId = coupon.id;
488	          couponDiscountCents = verdict.discountCents;
489	          couponLabel = verdict.label;
490	          couponMaxRedemptions = coupon.maxRedemptions;
491	          couponFirstTimeOnly = coupon.firstTimeOnly;
492	          couponExcludeActiveCustomers = coupon.excludeActiveCustomers;
493	          couponTrialDays = coupon.trialDays;
494	        } else {
495	          couponError = verdict.error;
496	        }
497	      }
498	    }
499	  }
500	
501	  const preDiscountChargeCents = introFirstTermPlanCents - couponDiscountCents + ipCents + extraDiskCents + backupCents;
502	  // CREATOR PARTNER PROGRAM: fold in the customer's 50%-off-first-purchase /
503	  // 10%-off-every-purchase-after discount (0 for the overwhelming majority never
504	  // attached to a partner). Applied on top of every other discount (intro,
505	  // coupon) — the customer's LAST price, not a second competing formula — and
506	  // covers every line (plan, dedicated IP, extra disk, backup): nothing on this
507	  // side excludes the dedicated IP add-on, only the PARTNER'S COMMISSION does
508	  // (lib/partner-commission.ts's separate, unrelated exclusion rule).
509	  const partnerDiscount = await partnerDiscountForNewOrder(opts?.userId);
510	  const partnerDiscountCents = partnerDiscountCentsFor(preDiscountChargeCents, partnerDiscount.percent);
511	  const chargeCents = preDiscountChargeCents - partnerDiscountCents;
512	  // The RECURRING rate this customer's account carries going forward — always the
513	  // 10% recurring tier (never the 50% first-purchase tier: by the time this order
514	  // renews, the first-purchase discount will already have been spent, whether it
515	  // was spent HERE or on some earlier purchase) — used only for the "renews at
516	  // $X" caption below, via renewalTotalCents.
517	  const partnerRenewalDiscount = await partnerDiscountForRenewal(opts?.userId);
518	  // What THIS order actually renews at, every cycle, forever — the number the
519	  // wizard's "Then $X every {term}" caption must show. Renewals never carry a
520	  // coupon or an intro discount (both are strictly first-term-only — see
521	  // introRenewalMonthly's own comment and lib/renewal-charge.ts, the ONE
522	  // renewal formula every real charge uses), so this is `regularPlanCents`
523	  // (the term-priced plan, no discount) plus every recurring add-on line at
524	  // FULL price — the exact same sum renewalCharge() computes for the real
525	  // charge, just assembled from this function's own already-computed parts
526	  // instead of re-deriving it. Fixed live 2026-09-14: the wizard was instead
527	  // showing `introRenewalMonthly` (== bare plan.priceCents, meant only for
528	  // the narrower "intro price renews at $X/mo" caption on plans with an
529	  // admin intro rate) for EVERY order, so a server bought with Backup Plus
530	  // or a dedicated IP quoted a renewal price that silently excluded them —
531	  // correct on the invoice and the real recurring charge the whole time, just
532	  // wrong on the one screen a customer actually reads before paying.
533	  const renewalPreDiscountCents = regularPlanCents + ipCents + extraDiskCents + backupCents;
534	  const renewalTotalCents =
535	    renewalPreDiscountCents - partnerDiscountCentsFor(renewalPreDiscountCents, partnerRenewalDiscount.percent);
536	  return {
537	    plan,
538	    os,
539	    term,
540	    chargeCents,
541	    // Creator Partner Program (0 / "NONE" for every customer not attached to an
