265	/**
266	 * Validate + price a game order without placing it. Throws GameOrderError on any
267	 * problem. Pure of side effects beyond reads. The price is the whole truth about
268	 * what this order costs; the caller (wallet split, review step, checkout stamp)
269	 * quotes from THIS so what the customer sees is what settles.
270	 */
271	export async function gameOrderQuote(
272	  intent: GameOrderIntent,
273	  opts?: {
274	    /**
275	     * CREATOR PARTNER PROGRAM (2026-09-26): see lib/order.ts orderQuote's own
276	     * doc comment on the identical option — same optional, additive, 0%-by-
277	     * default behavior. A game server is never a domain, so this always
278	     * resolves through the non-domain path.
279	     */
280	    userId?: string;
281	  },
282	): Promise<GameOrderQuote> {
283	  const term = normalizeProductTerm(intent.termMonths);
284	
285	  const gp = await db.gamePlan.findUnique({
286	    where: { id: intent.gamePlanId },
287	    include: { basePlan: true },
288	  });
289	  // A ONE-OFF CUSTOM game tier (lib/custom-plan.ts createCustomGamePlan, "build a
290	  // custom server") and its backing base Plan are both deliberately created
291	  // `active: false` — see the matching comment on lib/order.ts orderQuote's own
292	  // gate for why (30+ untouched `where: { active: true }` catalog queries across
293	  // this codebase must never surface either row generically). `sortOrder` is the
294	  // marker reserved for exactly this row shape, accepted here as an alternative.
295	  if (!gp || (!gp.active && gp.sortOrder !== CUSTOM_PLAN_SORT_ORDER)) {
296	    throw new GameOrderError("That game plan isn't available.");
297	  }
298	  if (!gp.basePlan?.active && gp.basePlan?.sortOrder !== CUSTOM_PLAN_SORT_ORDER) {
299	    throw new GameOrderError("Provisioning is temporarily unavailable for this game.");
300	  }
301	  if (!GAME_FAMILIES.includes(gp.gameFamily as GameFamily)) {
302	    throw new GameOrderError("Unknown game family.");
303	  }
304	  // DayZ's dedicated-server depot rejects anonymous SteamCMD login — every
305	  // order needs Nxeon's own dedicated Steam account (see lib/dayz-steam.ts).
306	  // Checked on every quote (not just at final order placement, unlike CS2's
307	  // GSLT auto-mint below, which is deliberately deferred to avoid burning
308	  // Valve's rate-limited account budget on live-preview keystrokes) because
309	  // this is a free, local boolean check with no external cost — so the
310	  // wizard can show an honest "not available yet" immediately rather than
311	  // only after checkout. Never let an order through that would just
312	  // crash-loop on SteamCMD's own login rejection.
313	  if (gp.gameFamily === "dayz" && !dayzSteamConfigured()) {
314	    throw new GameOrderError("DayZ hosting isn't available yet — check back soon, or contact support.");
315	  }
316	
317	  // Resolve the game image: the tier's own OsTemplate, else any active image for
318	  // this family. A game server can't provision without an image.
319	  let osTemplateId = gp.osTemplateId;
320	  if (osTemplateId) {
321	    const os = await db.osTemplate.findUnique({ where: { id: osTemplateId } });
322	    if (!os?.active) osTemplateId = null;
323	  }
324	  if (!osTemplateId) {
325	    const os = await db.osTemplate.findFirst({
326	      where: { family: gp.gameFamily, category: "APPLICATION", active: true },
327	      orderBy: { sortOrder: "asc" },
328	    });
329	    if (!os) throw new GameOrderError("No game image is configured for this game yet.");
330	    osTemplateId = os.id;
331	  }
332	
333	  // Hostname: validate a provided one strictly, else auto-generate a safe one.
334	  const rawHost = (intent.hostname ?? "").trim().toLowerCase();
335	  let hostname = rawHost;
336	  if (hostname === "") {
337	    hostname = `${gp.gameFamily}-${randSuffix()}`;
338	  } else if (!(hostname.length >= 3 && hostname.length <= 40 && HOSTNAME_RE.test(hostname))) {
339	    throw new GameOrderError(
340	      "Hostname must be 3–40 characters, using only letters, digits and hyphens, and cannot start or end with a hyphen.",
341	    );
342	  }
343	
344	  const label = (intent.serverName ?? "").trim().slice(0, 60) || null;
345	
346	  // Per-game setup: variant + gameplay settings, validated against the family
347	  // schema. Families without a customization schema (e.g. Terraria) carry no
348	  // variant and no gameplay values — the wizard shows only identity fields for them.
349	  const schema = schemaFor(gp.gameFamily);
350	  let variant = "";
351	  let values: Record<string, string | number | boolean> = {};
352	  if (schema) {
353	    variant = (intent.variant ?? "").trim() || schema.defaultVariant;
354	    if (!isValidVariant(gp.gameFamily, variant)) {
355	      throw new GameOrderError("Choose a valid server type for this game.");
356	    }
357	    const res = validateConfig(gp.gameFamily, intent.config ?? {});
358	    if (!res.ok) throw new GameOrderError(res.error);
359	    values = res.values;
360	  }
361	
362	  // A customer-chosen `<subdomain>.play.nxeon.cloud`, required at checkout
363	  // for every family with a real client-side hostname-connect story (see
364	  // lib/game-subdomain.ts — the free tier's own name rules, shared so the
365	  // two products can never disagree on what's valid or taken). Java
366	  // Minecraft gets a full A+SRV pair (players type only the subdomain);
367	  // Bedrock and everything in `HOSTNAME_CONNECT_FAMILIES` (lib/games.ts —
368	  // confirmed via real per-title research, not assumed) get an A record
369	  // only (players still type the port alongside it — none of them support
370	  // SRV) — worth less on its own, but still a memorable hostname instead of
371	  // a raw IP, and one that survives the underlying IP changing. Every other
372	  // family has no confirmed client-side hostname story, so this stays null
373	  // for them.
374	  let subdomain: string | null = null;
375	  if (gp.gameFamily === "minecraft" || gp.gameFamily === "bedrock" || HOSTNAME_CONNECT_FAMILIES.has(gp.gameFamily as GameFamily)) {
376	    const sub = (intent.subdomain ?? "").trim().toLowerCase();
377	    if (!sub) throw new GameOrderError("Pick a subdomain for your server — this is how players will connect.");
378	    const formatError = validateSubdomainFormat(sub);
379	    if (formatError) throw new GameOrderError(formatError);
380	    if (!(await isSubdomainAvailable(sub))) throw new GameOrderError("That subdomain is taken — try another.");
381	    subdomain = sub;
382	  }
383	
384	  // Price: DB-fed base × term, annual discount resolved ONCE and frozen at sale.
385	  // Every seeded plan is `termMonths: 1`, so monthlyCents === priceCents; the
386	  // divisor keeps the maths correct if a multi-month base plan is ever configured.
387	  const annualPct = await annualDiscountPct();
388	  const monthlyCents = Math.round(gp.priceCents / Math.max(1, gp.termMonths));
389	  const wantIp = !!intent.dedicatedIp;
390	  const ipCents = wantIp ? (await dedicatedIpMonthlyCents()) * term : 0;
391	  const planChargeCents = termPriceCents(monthlyCents, term, annualPct);
392	  // GRANDFATHER PROGRAM: GamePlan now carries the same introPriceCents/
393	  // introTermMonths columns Plan has always had (lib/intro-pricing.ts's
394	  // helpers are generic over any `{priceCents}` row, so this is the exact
395	  // same math VPS uses, not a second formula). A plan without an intro price
396	  // set (introMonthlyCents null) sees introDiscountCents === 0 and
397	  // introFirstTermPlanCents === planChargeCents — byte-for-byte the pre-intro
398	  // behavior, so every existing game plan is unaffected until an admin
399	  // actually sets one.
400	  const introMonthlyCents = planIntroMonthlyCents(gp);
401	  const introTermMonthsVal = planIntroTermMonths(gp);
402	  const introDiscountCents = introFirstTermDiscountCents(monthlyCents, introMonthlyCents, term, introTermMonthsVal, annualPct);
403	  const introFirstTermPlanCents = Math.max(0, planChargeCents - introDiscountCents);
404	  const introPercent = introSoldPercent(planChargeCents, introDiscountCents);
405	
406	  // Optional checkout coupon: discounts the PLAN portion only (never the
407	  // dedicated-IP add-on), same shared math + same "never widen on a bad code"
408	  // discipline as lib/order.ts orderQuote's VPS coupon block. The atomic
409	  // redemption claim (count + per-user + per-IP guards) happens in
410	  // placeGameOrder, not here — this is read-only pricing.
411	  let couponId: string | null = null;
412	  let couponDiscountCents = 0;
413	  let couponLabel = "";
414	  let couponError = "";
415	  let couponMaxRedemptions: number | null = null;
416	  let couponFirstTimeOnly = false;
417	  let couponExcludeActiveCustomers = false;
418	  let couponTrialDays: number | null = null;
419	  const code = (intent.couponCode ?? "").trim().toUpperCase();
420	  if (code) {
421	    if (!(await getSettingBool("coupons_enabled", true))) {
422	      couponError = "Promo codes are currently disabled.";
423	    } else {
424	      const coupon = await db.coupon.findUnique({ where: { code } });
425	      if (!coupon) {
426	        couponError = "That code isn’t valid.";
427	      } else {
428	        const verdict = couponOrderDiscountCents(
429	          {
430	            kind: coupon.kind,
431	            value: coupon.value,
432	            serviceKind: coupon.serviceKind,
433	            planSlug: coupon.planSlug,
434	            maxTermMonths: coupon.maxTermMonths,
435	            active: coupon.active,
436	            expiresAt: coupon.expiresAt,
437	            maxRedemptions: coupon.maxRedemptions,
438	            timesRedeemed: coupon.timesRedeemed,
439	            minAmountCents: coupon.minAmountCents,
440	          },
441	          {
442	            serviceKind: "GAME",
443	            // Game plans have no slug of their own — coupon.planSlug is matched
444	            // against the game family instead, so "GAMESALE" can be scoped to
445	            // e.g. "valheim" the same way a VPS coupon locks to "starter".
446	            planSlug: gp.gameFamily,
447	            planMonthlyCents: monthlyCents,
448	            termMonths: term,
449	            // The intro-discounted first-term charge, not the full regular
450	            // total — a coupon stacks on top of whatever this term is
451	            // actually being sold at, exactly like lib/order.ts's VPS path.
452	            planChargeCents: introFirstTermPlanCents,
453	          },
454	          new Date(),
455	        );
456	        if (verdict.ok) {
457	          couponId = coupon.id;
458	          couponDiscountCents = verdict.discountCents;
459	          couponLabel = verdict.label;
460	          couponMaxRedemptions = coupon.maxRedemptions;
461	          couponFirstTimeOnly = coupon.firstTimeOnly;
462	          couponExcludeActiveCustomers = coupon.excludeActiveCustomers;
463	          couponTrialDays = coupon.trialDays;
464	        } else {
465	          couponError = verdict.error;
466	        }
467	      }
468	    }
469	  }
470	
471	  const preDiscountChargeCents = introFirstTermPlanCents - couponDiscountCents + ipCents;
472	  // CREATOR PARTNER PROGRAM — see lib/order.ts orderQuote's own doc comment on
473	  // the identical block; same math, same stacking order (on top of intro/coupon).
474	  const partnerDiscount = await partnerDiscountForNewOrder(opts?.userId);
475	  const partnerDiscountCents = partnerDiscountCentsFor(preDiscountChargeCents, partnerDiscount.percent);
476	  const chargeCents = preDiscountChargeCents - partnerDiscountCents;
477	  // Always the RECURRING (10%) tier for the "renews at" caption — see
478	  // lib/order.ts orderQuote's identical `partnerRenewalDiscount` comment.
479	  const partnerRenewalDiscount = await partnerDiscountForRenewal(opts?.userId);
480	  const renewalPreDiscountCents = planChargeCents + ipCents;
481	  const renewalTotalCents =
482	    renewalPreDiscountCents - partnerDiscountCentsFor(renewalPreDiscountCents, partnerRenewalDiscount.percent);
483	
484	  return {
485	    gamePlanId: gp.id,
486	    gameFamily: gp.gameFamily,
487	    planName: gp.name,
488	    basePlanId: gp.basePlanId,
489	    ramMB: gp.basePlan.ramMB,
490	    osTemplateId,
491	    term,
492	    annualPct,
493	    monthlyCents,
494	    chargeCents,
495	    /**
496	     * The RAW GamePlan.priceCents this order was placed against — same units
497	     * `renewalCharge` divides by `gamePlan.termMonths` — NOT a term total.
498	     * This is what a server's grandfathered renewal rate freezes to; it is
499	     * deliberately not `regularPlanCents`/`chargeCents` below, which already
500	     * have this ORDER's term length and annual discount baked in and would
501	     * freeze the wrong (much larger, for a multi-month term) number.
