70	   * attached to an active partner — the overwhelming majority). The wizard shows
71	   * this BEFORE checkout so the discount is visible ahead of the first purchase,
72	   * per the program's own requirement.
73	   */
74	  partnerDiscountCents: number;
75	  partnerDiscountPercent: number;
76	  partnerDiscountTier: "FIRST" | "RECURRING" | "NONE";
77	  partnerName: string | null;
78	};
79	
80	export type QuoteResult = QuotedPrice | { ok: false; error: string };
81	
82	/**
83	 * Price a wizard selection. Read-only.
84	 *
85	 * Errors are RETURNED, not thrown: an incomplete selection (no plan chosen yet)
86	 * is the normal state of a wizard, not an exception, and the cart should show
87	 * nothing rather than an error boundary.
88	 */
89	export async function quoteOrder(intent: OrderIntent): Promise<QuoteResult> {
90	  const user = await requireUser();
91	  try {
92	    let q = await orderQuote(intent, { userId: user.id });
93	    const taxCents = 0; // orderQuote returns net; tax is applied on the charge leg.
94	    // Catalog-level checks (service/plan/term/dates/global cap) already ran
95	    // inside orderQuote; this adds the two ACCOUNT-level ones it can't see —
96	    // see couponAccountEligibilityError's own doc comment for why the preview
97	    // needs this too, not just the real reservation at pay time.
98	    let couponError: string | null = q.couponError ?? null;
99	    if (q.couponId && (q.couponDiscountCents ?? 0) > 0) {
100	      const ineligible = await couponAccountEligibilityError({
101	        userId: user.id,
102	        firstTimeOnly: q.couponFirstTimeOnly,
103	        excludeActiveCustomers: q.couponExcludeActiveCustomers,
104	        couponId: q.couponId,
105	        ipHash: hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null,
106	      });
107	      if (ineligible) {
108	        // Re-price WITHOUT the coupon, as payAndDeploy's card path does when
109	        // the hold is refused — the partner discount is a percentage of the
110	        // post-coupon amount, so "adding the coupon back" left it on the wrong
111	        // base (2026-09-28; see lib/nx/quote-game.ts's identical fix).
112	        q = await orderQuote({ ...intent, couponCode: undefined }, { userId: user.id });
113	        couponError = ineligible;
114	      }
115	    }
116	    const couponDiscountCents = q.couponDiscountCents ?? 0;
117	    const couponLabel: string | null = q.couponLabel ?? null;
118	    const chargeCents = q.chargeCents;
119	    return {
120	      ok: true,
121	      chargeCents,
122	      taxCents,
123	      totalCents: chargeCents + taxCents,
124	      months: q.term.months,
125	      regularPlanCents: q.regularPlanCents,
126	      promoCreditCents: q.promoCreditCents ?? 0,
127	      /* STRICT: the promo is named only when it actually put money back on THIS
128	         order. `discountPercent` is a property of the promo, not of this quote —
129	         first-month-free carries one while applying to hosting only, which is
130	         how a VPS order ended up captioned "First month free" while being
131	         charged in full. A percentage promo that really did apply shows up as
132	         chargeCents below regularPlanCents, and the struck-through "was" price
133	         already tells that story. */
134	      promoName: (q.promoCreditCents ?? 0) > 0 ? q.promo?.name ?? "" : "",
135	      promoPercent: q.promo?.discountPercent ?? 0,
136	      couponLabel,
137	      couponDiscountCents,
138	      couponError,
139	      extraDiskCents: q.extraDiskCents ?? 0,
140	      backupCents: q.backupCents ?? 0,
141	      introMonthlyCents: q.introMonthlyCents || null,
142	      // Only meaningful alongside an intro rate; without one it is just the
143	      // regular price restated in amber, which reads as a warning.
144	      introRenewalMonthly: q.introMonthlyCents ? q.introRenewalMonthly ?? null : null,
145	      renewalTotalCents: q.renewalTotalCents ?? q.chargeCents,
146	      partnerDiscountCents: q.partnerDiscountCents ?? 0,
147	      partnerDiscountPercent: q.partnerDiscountPercent ?? 0,
148	      partnerDiscountTier: q.partnerDiscountTier ?? "NONE",
149	      partnerName: q.partnerName ?? null,
150	    };
151	  } catch (e) {
152	    if (e instanceof OrderError) return { ok: false, error: e.message };
153	    // Never leak an internal message to the browser.
154	    return { ok: false, error: "Couldn't price that selection." };
155	  }
156	}
