  // A custom Plan/GamePlan row is created `active: false` (see lib/custom-plan.ts)
  // so it never surfaces in the 30+ untouched `where: { active: true }`
  // catalog/resize/marketing queries across this codebase, but orderQuote /
  // gameOrderQuote must still accept it as a purchase target for the one order
  // that just built it — via THIS exact sortOrder, not a magic number re-declared
  // in each file. Reserved well above the live premade ladder (sortOrder 1-5) and
  // NxCloud's backing plans (900-903), so it can never collide with either.
  assert.equal(CUSTOM_PLAN_SORT_ORDER, 999);
  assert.ok(CUSTOM_PLAN_SORT_ORDER > 900, "must sit above the NxCloud backing-plan range");
});

test("name and slug are stable, human-readable and slug fits the DB column cap", () => {
  const spec = { cpuCores: 8, ramMB: 32768, diskGB: 200 };
  assert.equal(customPlanName(spec), "Custom 8 vCPU / 32 GB / 200 GB Disk");
  const slug = customPlanSlug(spec, "abc123");
  assert.equal(slug, "custom-8c32g-abc123");
  // adminSavePlan's zod schema caps slug at 30 chars — even at the ceiling.
  const bigSlug = customPlanSlug({ cpuCores: CEILING.maxCpuCores, ramMB: CEILING.maxRamMB, diskGB: CEILING.maxDiskGB }, "abc123");
  assert.ok(bigSlug.length <= 30, `slug too long: ${bigSlug}`);
});

