cd /tank/dev-worktrees/custom-plan-intro-sales && cat > /tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad/anchor-check.ts <<'EOF'
import { readFileSync } from "node:fs";
import {
  CUSTOM_GAME_PLAN_DEFAULT_PER_VCPU_CENTS, parseGameFamilyRatesOverride, gameCustomFloor,
  computeCustomGamePlanPriceCents, computeCustomIntroPriceCents, customPlanIntroTerms,
} from "/tank/dev-worktrees/custom-plan-intro-sales/lib/custom-plan-pricing.ts";
const vpsFloor = { cpuCores: 4, ramMB: 16384, diskGB: 120, priceCents: 4750, bandwidthTB: 8 };
const ram = parseGameFamilyRatesOverride("");
const rows = readFileSync(process.argv[2], "utf8").trim().split("\n").filter(l => l.includes("|"));
const out: string[] = [];
for (const r of rows) {
  const [fam, c, m, d, p, ip] = r.split("|");
  const anchor = { cpuCores: +c, ramMB: +m, diskGB: +d, priceCents: +p };
  const floor = gameCustomFloor(vpsFloor, anchor);
  const rates = { perVcpuCents: CUSTOM_GAME_PLAN_DEFAULT_PER_VCPU_CENTS, perRamGbCents: ram[fam] ?? 0, perDiskGbCents: 10 };
  // cheapest real custom build: +1 GB RAM over the floor (what the wizard's "from" uses among others)
  const cands = [
    { ...floor, cpuCores: floor.cpuCores + 1 }, { ...floor, ramMB: floor.ramMB + 1024 }, { ...floor, diskGB: floor.diskGB + 10 },
  ].map(s => computeCustomGamePlanPriceCents(s, anchor, rates, vpsFloor.priceCents));
  const minP = Math.min(...cands);
  const anchorIntro = +ip >= 0 ? +ip : null;
  const blanket = computeCustomIntroPriceCents(minP, { percent: 30, anchorIntroCents: -1 });
  const inherited = computeCustomIntroPriceCents(minP, customPlanIntroTerms(anchorIntro, 30));
  const anchorFirstTerm = anchorIntro ?? +p;
  out.push(`${fam.padEnd(16)} top=${p} topIntro=${anchorIntro ?? "none"} customMin=${minP} blanket30=${blanket} inherited=${inherited} ${blanket! <= anchorFirstTerm ? "<-- blanket 30% UNDERCUTS top tier first term" : ""}`);
}
console.log(out.join("\n"));
EOF
