// $39.99 top tier. It clamps to $40.00 there, and the full 30% applies from about
// $57.15/mo up. The other 46 families and VPS never touch the clamp at 30%.
export const CUSTOM_PLAN_DEFAULT_INTRO_PERCENT = 30;

/** The intro terms for a custom build. `null` = sold at the regular price from
 *  day one (the setting is 0). */
export type CustomPlanIntro = {
  /** Percent off the FIRST term, 0 < pct <= 90 (clamped like `annual_discount_percent`). */
  percent: number;
  /** What the plan being extended (VPS Max / the family's top tier) charges for
   *  ITS first term, monthly: its validated intro price (lib/intro-pricing.ts
   *  `planIntroMonthlyCents`), else its regular `priceCents`. The anti-undercut floor. */
  anchorFirstTermCents: number;
};

/** Build the intro terms from the anchor's first-term price and the admin percent.
 *  Pure, so the deploy page and the server quote path construct it the same way. */
export function customPlanIntroTerms(anchorFirstTermCents: number, percent: number): CustomPlanIntro | null {
  if (!Number.isFinite(anchorFirstTermCents)) return null;
  const pct = Number.isFinite(percent) ? Math.min(90, Math.max(0, percent)) : 0;
  if (pct <= 0) return null;
  return { percent: pct, anchorFirstTermCents: Math.round(anchorFirstTermCents) };
}

/**
 * A custom build's intro (first-term) MONTHLY price, or null when it has none.
 * Integer arithmetic (`price × (100 − pct) / 100`) so a half-cent lands the same
 * way every time. `round(price × 0.7)` in floating point computes 5125 × 0.7 as
 * 3587.4999… and rounds it DOWN to 3587, where the integer form gives 3588.
 * Returns null unless the result is genuinely below `priceCents`, mirroring
 * `planIntroMonthlyCents`'s own rule that an intro can never raise a charge.
 */
export function computeCustomIntroPriceCents(priceCents: number, intro: CustomPlanIntro | null): number | null {
  if (!intro || !Number.isFinite(priceCents) || priceCents <= 0) return null;
  const pct = Math.min(90, Math.max(0, intro.percent));
  if (pct <= 0) return null;
  const discounted = Math.round((priceCents * (100 - pct)) / 100);
  const cents = Math.max(discounted, intro.anchorFirstTermCents + 1);
  return cents < priceCents ? cents : null;
}

