p='test/custom-plan-pricing.test.ts'
s=open(p).read()
start=s.index('// ─── intro (first-term) price on a custom build')
s=s[:start]+'''// ─── intro (first-term) price on a custom build ─────────────────────────────
// Anchors read from prod `nxeon` 2026-09-29 (read-only): VPS Max is $47.50 with a
// $32.99 intro; armareforger's top tier is $39.99 with NO intro price.
const MAX_INTRO = customPlanIntroTerms(3299, CUSTOM_PLAN_DEFAULT_INTRO_PERCENT);

test("default intro is 30% off: round(price x 0.70), per the owner's policy", () => {
  assert.equal(CUSTOM_PLAN_DEFAULT_INTRO_PERCENT, 30);
  assert.equal(computeCustomIntroPriceCents(6000, MAX_INTRO), 4200);
  assert.equal(computeCustomIntroPriceCents(4751, MAX_INTRO), 3326); // 3325.7
});

test("intro rounds half-cents up in integer arithmetic, not float (5125 x 0.7 = 3587.5)", () => {
  // Math.round(5125 * 0.7) is 3587 because the float product is 3587.4999...
  assert.equal(computeCustomIntroPriceCents(5125, MAX_INTRO), 3588);
});

test("a 0% (or negative / NaN) setting turns the intro off; the percent is clamped to 90", () => {
  assert.equal(customPlanIntroTerms(3299, 0), null);
  assert.equal(customPlanIntroTerms(3299, -5), null);
  assert.equal(customPlanIntroTerms(3299, Number.NaN), null);
  assert.equal(customPlanIntroTerms(3299, 150)?.percent, 90);
  assert.equal(computeCustomIntroPriceCents(9999, null), null);
});

test("a decimal percent works (30.5 = the catalog's own ~0.695 ratio)", () => {
  const intro = customPlanIntroTerms(3299, 30.5);
  assert.equal(computeCustomIntroPriceCents(10000, intro), 6950);
});

test("anti-undercut: a family with NO intro price clamps to one cent above its top tier's regular price", () => {
  // armareforger (prod): top tier $39.99, no intro, so its first term costs $39.99.
  // Its smallest custom build is $47.99; 30% off would be $33.59, cheaper than
  // the smaller top tier's first term, so it clamps to $40.00.
  const arma = customPlanIntroTerms(3999, 30);
  assert.equal(computeCustomIntroPriceCents(4799, arma), 4000);
  // From 5715 up, 30% off clears the floor on its own: the clamp stops binding.
  assert.equal(computeCustomIntroPriceCents(5715, arma), 4001);
  assert.equal(computeCustomIntroPriceCents(8000, arma), 5600);
});

test("anti-undercut: a steep admin percent can't push a custom first term below Max's", () => {
  const steep = customPlanIntroTerms(3299, 60);
  assert.equal(computeCustomIntroPriceCents(5000, steep), 3300);
});

test("anti-undercut never binds at the default 30% for any VPS custom price", () => {
  // Every VPS custom build is priced >= Max + 1 = 4751.
  for (let price = 4751; price <= 60000; price += 7) {
    const intro = computeCustomIntroPriceCents(price, MAX_INTRO)!;
    assert.equal(intro, Math.round((price * 70) / 100), `clamp fired at ${price}`);
    assert.ok(intro > 3299 && intro < price);
  }
});

test("an intro can never RAISE the price (mirrors planIntroMonthlyCents's rule)", () => {
  // Anchor first term so high the clamp would reach the price itself: no intro.
  const odd = customPlanIntroTerms(4999, 30);
  assert.equal(computeCustomIntroPriceCents(5000, odd), null);
});
'''
open(p,'w').write(s)
EOF
