/**
 * REAL end-to-end verification for `adminRenewServerNow` / `renewServerImmediately`
 * (2026-09-25) — actually exercises the wallet-then-card renewal path against a
 * real, isolated Postgres database and a real Stripe TEST-mode account, not
 * mocks. Run manually (not part of `npm test` — see test/admin-renew-now.test.ts's
 * own header comment for why: importing worker/billing.ts / lib/db.ts into the
 * standard suite would connect it to a live database at import time).
 *
 * SAFETY: this script only ever runs against whatever DATABASE_URL is in the
 * environment when it starts, and refuses outright unless that database's name
 * is `nxeon_verify` — a disposable database created solely for this
 * verification, never staging, never production. See CLAUDE.md's own
 * documented incident (scripts/db-target-guard.ts) for why a writing script
 * must never trust ambient .env resolution without saying, out loud, which
 * database it believes it's about to write to.
 *
 * Usage:
 *   npx tsx scripts/verify-admin-renew-now.ts
 */
import { db } from "../lib/db";
import { stripe, stripeConfigured } from "../lib/stripe";
import { renewServerImmediately, type DueServer } from "../worker/billing";
import { dunningConfig } from "../lib/dunning-config";

function must(cond: boolean, msg: string): asserts cond {
  if (!cond) throw new Error(`REFUSED: ${msg}`);
}

async function main() {
  const url = process.env.DATABASE_URL ?? "";
  const dbName = /\/([^/?]+)(\?|$)/.exec(url)?.[1];
  must(dbName === "nxeon_verify", `DATABASE_URL must point at nxeon_verify, resolved "${dbName}" instead — refusing to run against anything else.`);
  must(stripeConfigured(), "STRIPE_SECRET_KEY is not set — cannot verify the card leg for real.");
  const key = process.env.STRIPE_SECRET_KEY ?? "";
  must(key.startsWith("sk_test_"), "STRIPE_SECRET_KEY is not a TEST key — refusing to run a real-money key through this script.");

  console.log(`[verify] target database: ${dbName}`);
  console.log(`[verify] Stripe key: ${key.slice(0, 12)}… (test mode)`);

  // ---- fixtures --------------------------------------------------------
  const plan = await db.plan.upsert({
    where: { slug: "verify-starter" },
    create: { slug: "verify-starter", name: "Verify Starter", cpuCores: 1, ramMB: 1024, diskGB: 20, priceCents: 1000 },
    update: {},
  });
  let gamePlan = await db.gamePlan.findFirst({ where: { name: "Verify Minecraft" } });
  if (!gamePlan) {
    gamePlan = await db.gamePlan.create({
      data: {
        name: "Verify Minecraft",
        gameFamily: "minecraft",
        cpuCores: 1,
        ramMB: 2048,
        diskGB: 10,
        priceCents: 499,
        termMonths: 1,
        basePlanId: plan.id,
      },
    });
  }
  const osTemplate = await db.osTemplate.upsert({
    where: { slug: "verify-ubuntu" },
    create: { slug: "verify-ubuntu", name: "Verify Ubuntu", vmid: 9999 },
    update: {},
  });

  const cfg = await dunningConfig();
  const prices = { ipMonthlyCents: 0, extraDiskPerGbCents: 0, backupPlusCents: 0, annualDiscountPct: 0 };
  const ctxFor = () => ({ now: new Date(), cfg, prices, taxRatePercent: 0, taxCountry: "US" });

  let n = 0;
  const nextEmail = () => `verify-${Date.now()}-${++n}@nxeon.test`;

  async function makeUser(opts: { balanceCents: number; withCard?: "visa" | "declined" | "insufficient" }) {
    const user = await db.user.create({
      data: { email: nextEmail(), passwordHash: "x", name: "Verify User", balanceCents: opts.balanceCents },
    });
    if (opts.withCard) {
      const customer = await stripe().customers.create({ email: user.email, name: user.name });
      // `pm_card_visa` is Stripe's shortcut PaymentMethod id — safe to attach

    const c = await db.coupon.findUnique({ where: { id: opts.couponId }, select: { timesRedeemed: true, active: true } });
    if (!c || !c.active || c.timesRedeemed >= opts.maxRedemptions) return { ok: false, error: "This code has reached its redemption limit." };
  }
  return { ok: true };
}

export async function placeOrder(
  user: User,
  intent: OrderIntent,
  sold?: OrderPrice | null,
  opts?: {
    ipHash?: string | null;
    campaign?: string;
    promoReservationToken?: string | null;
    couponReservationToken?: string | null;
  },
): Promise<string> {
  const quote = await orderQuote(intent, { userId: user.id });
  const { plan, os, term, promo, promoCreditCents, extraDiskGB, extraDiskMonthlyCents, extraDiskCents, backupTier, backupMonthlyCents, backupCents, ipCents, partnerDiscountCents, partnerDiscountTier } = quote;

  // Resolve the ACTUAL hostname this server will get before anything below
  // (invoice line items, the wallet transaction description, the Server row
  // itself) reads `intent.hostname` — so every one of those stays honest
  // about what the customer's server is really named instead of quoting the
  // pre-collision name. orderQuote (above) already enforced the format via
  // orderSchema; this only resolves UNIQUENESS. See lib/hostname.ts's doc
 * the customer consented to instead of re-pricing against a rate that changed in
 * between. The wallet path omits it and pays the fresh quote it computed moments
 * ago. This mirrors `sold` in lib/order.ts placeOrder.
 *
 * Callers must ensure funds exist (the card leg pre-credits the wallet, the wallet
 * path is gated by the balance check in the action). This still enforces the
 * balance and throws GameOrderError("Insufficient balance…") otherwise — no overdraft.
 */
export async function placeGameOrder(
  user: User,
  intent: GameOrderIntent,
  sold?: GameOrderPrice | null,
  /** CARD path only: the hold `payAndDeployGame` reserved before the card was
   *  charged (see reserveOrderCoupon), confirmed here — RESERVED→CONSUMED —
   *  inside the same tx that commits the order. Mirrors lib/order.ts
   *  placeOrder's `opts.couponReservationToken` exactly. */
  couponReservationToken?: string | null,
): Promise<string> {
  const quote = await gameOrderQuote(intent, { userId: user.id });

  // Resolve the ACTUAL hostname this server will get, now that the order is
  // really being placed (NOT inside gameOrderQuote, which the wizard calls on
  // every keystroke for a live price preview and has no business hitting the
  // DB or handing out a name it might never use). gameOrderQuote already
  // validated the format (or generated the "<family>-<rand>" default); this
  // only resolves UNIQUENESS, auto-suffixing on collision instead of letting
  // two customers' servers end up with the same hostname. See lib/hostname.ts.
  quote.hostname = await resolveUniqueHostname(quote.hostname, quote.gameFamily);

  // CS2 needs a Steam Game Server Login Token to register with matchmaking at
  // all (SRCDS_TOKEN, no longer a required checkout field as of 2026-09-17 —
  // see lib/game-config.ts's field comment). Mint one automatically, ONCE,
  // here at actual order placement — never in gameOrderQuote, which the
  // wizard calls on every keystroke for a live price preview and would burn
  // through Valve's 1000-account-per-key budget on customers who never buy.
  // A customer who pasted their own token is left alone; a Steam API hiccup
  // degrades to "no token yet" (server still deploys and runs, just isn't
  // listed on matchmaking until one is added from the dashboard) rather than
  // failing the whole paid order over it.
  if (quote.gameFamily === "cs2" && !quote.values.SRCDS_TOKEN && steamGsltConfigured()) {
    try {
      const account = await createGameServerAccount(730, `nxeon:${quote.hostname}`);
      quote.values.SRCDS_TOKEN = account.loginToken;
      quote.values._SRCDS_TOKEN_STEAMID = account.steamid;
    } catch (e) {
      console.error(`[game-order] Steam GSLT auto-generation failed for ${quote.hostname}`, e);
    }
  }

  // Bill off the SOLD price when present (never re-priced after the card cleared),
  // else the fresh quote (which already folds in any valid coupon discount) —
  // this scalar is the whole truth about what this order costs.
  const chargeCents = sold?.chargeCents ?? quote.chargeCents;

  // Oversell guard — the VPS order path enforces this; game orders must too, or a
  // game server could commit host RAM past capacity.
  const capacity = await capacityCheck(quote.basePlanId);
  if (!capacity.ok) {
    throw new GameOrderError(capacity.reason ?? "The host is at capacity right now. Please try again shortly.");
  }

