/**
 * REAL verification of the custom-build intro price, against the STAGING DB and
 * Stripe TEST mode. quoted === created === orderQuote/gameOrderQuote charge ===
 * real Stripe PaymentIntent amount, then the real placeOrder/placeGameOrder
 * writes (termPromoPercent, grandfatheredRenewalCents, invoice, wallet), then
 * the real renewalCharge() on the created Server row.
 *
 * Run ONLY with the staging worker stopped (no VM gets provisioned); the script
 * deletes the Job + Server + custom rows it created afterwards.
 */
const WT = "/tank/dev-worktrees/custom-plan-intro-sales";
const { db } = await import(`${WT}/lib/db.ts`);
const { stripe, stripeConfigured } = await import(`${WT}/lib/stripe.ts`);
const cp = await import(`${WT}/lib/custom-plan.ts`);
const { orderQuote, placeOrder, orderPriceOf } = await import(`${WT}/lib/order.ts`);
const { gameOrderQuote, placeGameOrder } = await import(`${WT}/lib/game-order.ts`);
const { renewalCharge } = await import(`${WT}/lib/renewal-charge.ts`);
const { currentRenewalPrices } = await import(`${WT}/lib/admin-metrics.ts`);
const { annualDiscountPct } = await import(`${WT}/lib/annual-discount.ts`);
const { vpsTermPriceCents } = await import(`${WT}/lib/billing-terms.ts`);
const { introFirstTermDiscountCents } = await import(`${WT}/lib/intro-pricing.ts`);

function must(cond: unknown, msg: string): asserts cond {
  if (!cond) throw new Error(`FAILED: ${msg}`);
}
const $ = (c: number) => `$${(c / 100).toFixed(2)}`;

const dbName = /\/([^/?]+)(\?|$)/.exec(process.env.DATABASE_URL ?? "")?.[1];
must(dbName === "nxeon_staging", `DATABASE_URL must be nxeon_staging, got ${dbName}`);
must(stripeConfigured() && (process.env.STRIPE_SECRET_KEY ?? "").startsWith("sk_test_"), "need a Stripe TEST key");
console.log(`[verify] db=${dbName} stripe=${process.env.STRIPE_SECRET_KEY!.slice(0, 12)}… (test mode)`);

/** The "effective first-term monthly" the wizard prints, computed exactly as
 *  lib/actions-custom-plan.ts firstTermMatrix does (orderQuote's arithmetic). */
async function firstTermMonthly(price: number, intro: number, months: number) {
  const pct = await annualDiscountPct();
  const regular = vpsTermPriceCents(price, months, pct);
  return Math.round(Math.max(0, regular - introFirstTermDiscountCents(price, intro, months, null, pct)) / months);
}

const ts = Date.now().toString(36);
const created: { serverIds: string[]; planIds: string[]; gamePlanIds: string[] } = { serverIds: [], planIds: [], gamePlanIds: [] };

async function makeUser(tag: string) {
  return db.user.create({
    data: {
      email: `verify-custom-intro-${tag}-${ts}@nxeon.test`,
      passwordHash: "x",
      name: `Verify Custom Intro ${tag}`,
      balanceCents: 0,
      emailVerifiedAt: new Date(),
    },
  });
}

async function chargeCard(user: { id: string; email: string; name: string }, amount: number, what: string) {
  const customer = await stripe().customers.create({ email: user.email, name: user.name });
  const pi = await stripe().paymentIntents.create({
    amount,
    currency: "usd",
    customer: customer.id,
    payment_method: "pm_card_visa",
    confirm: true,
    automatic_payment_methods: { enabled: true, allow_redirects: "never" },
    description: `Nxeon staging verification: ${what}`,
    metadata: { purpose: "verify-custom-intro", userId: user.id },
  });
  must(pi.status === "succeeded", `PaymentIntent ${pi.id} status ${pi.status}`);
  must(pi.amount_received === amount, `PaymentIntent received ${pi.amount_received} != ${amount}`);
  // What the card path's confirm route does before placeOrder: credit the wallet
  // with exactly what the card collected; placeOrder then debits the order total.
  await db.user.update({ where: { id: user.id }, data: { balanceCents: { increment: pi.amount_received } } });
  return pi;
}

const results: Record<string, unknown>[] = [];

// ─── VPS case ───────────────────────────────────────────────────────────────
{
  const spec = { cpuCores: 8, ramMB: 32 * 1024, diskGB: 240 };
  const term = 1;
  const q = await cp.customPlanQuote(spec);
  must(q.ok, `VPS quote failed: ${!q.ok && q.reason}`);
  must(q.introPriceCents !== null, "VPS quote carries no intro price");
  const cap = await cp.customPlanCapacityCheck(spec);
  must(cap.ok, `VPS capacity: ${cap.reason}`);
  const previewFirstTerm = await firstTermMonthly(q.priceCents, q.introPriceCents!, term);

  const plan = await cp.createCustomPlan(spec);
  created.planIds.push(plan.id);
  const row = await db.plan.findUniqueOrThrow({ where: { id: plan.id } });
  must(row.priceCents === q.priceCents, `created price ${row.priceCents} != quoted ${q.priceCents}`);
  must(row.introPriceCents === q.introPriceCents, `created intro ${row.introPriceCents} != quoted ${q.introPriceCents}`);
  must(row.introTermMonths === null, "introTermMonths should be null");

  const os = await db.osTemplate.findFirstOrThrow({ where: { active: true, category: "PLAIN_OS", family: "ubuntu" }, orderBy: { sortOrder: "asc" } });
  const user = await makeUser("vps");
  const intent = { planId: plan.id, osTemplateId: os.id, hostname: `vi-${ts}`, termMonths: term };
  const oq = await orderQuote(intent, { userId: user.id });
  must(oq.chargeCents === q.introPriceCents, `orderQuote charge ${oq.chargeCents} != intro ${q.introPriceCents}`);
  must(oq.chargeCents === previewFirstTerm * term, `orderQuote charge ${oq.chargeCents} != preview first-term ${previewFirstTerm}`);
  must(oq.renewalTotalCents === q.priceCents, `renewal ${oq.renewalTotalCents} != regular ${q.priceCents}`);

  const pi = await chargeCard(user, oq.chargeCents, `custom VPS ${plan.name}`);
  const serverId = await placeOrder(user, intent, orderPriceOf(oq));
  created.serverIds.push(serverId);
  const s = await db.server.findUniqueOrThrow({ where: { id: serverId }, include: { plan: true, gamePlan: true } });
  const inv = await db.invoice.findFirst({ where: { serverId }, orderBy: { createdAt: "desc" } });
  const u2 = await db.user.findUniqueOrThrow({ where: { id: user.id } });
  const renewal = renewalCharge(s as never, await currentRenewalPrices());
  must((s as any).grandfatheredRenewalCents === q.priceCents, `grandfathered ${(s as any).grandfatheredRenewalCents} != ${q.priceCents}`);
  must(renewal.netCents === q.priceCents, `renewal net ${renewal.netCents} != regular ${q.priceCents}`);
  must(u2.balanceCents === 0, `wallet should net to 0, is ${u2.balanceCents}`);
  results.push({
    case: "VPS 8 vCPU / 32 GB / 240 GB, monthly",
    regularMonthly: $(q.priceCents),
    introQuoted: $(q.introPriceCents!),
    wizardFirstTermMonthly: $(previewFirstTerm),
    createdPlanRow: `${$(row.priceCents)} / intro ${$(row.introPriceCents!)}`,
    orderQuoteCharge: $(oq.chargeCents),
    stripe: `${pi.id} ${pi.status} ${$(pi.amount_received)}`,
    invoiceTotal: inv ? $(inv.totalCents ?? (inv as any).amountCents) : "(none)",
    termPromoPercent: s.termPromoPercent,
    grandfatheredRenewal: $((s as any).grandfatheredRenewalCents),
    renewalCharge: `${$(renewal.totalCents)} every ${renewal.months} mo`,
  });
}

// ─── GAME case (annual term, exercises the term-discount interplay) ────────
{
  const family = process.env.VERIFY_GAME_FAMILY ?? "rust";
  const term = 12;
  const q0 = await cp.customGamePlanQuote(family, { cpuCores: 99, ramMB: 1, diskGB: 1 });
  const f = q0.floor;
  const spec = { cpuCores: f.cpuCores + 4, ramMB: f.ramMB + 8 * 1024, diskGB: f.diskGB + 40 };
  const q = await cp.customGamePlanQuote(family, spec);
  must(q.ok, `game quote failed: ${!q.ok && q.reason}`);
  must(q.introPriceCents !== null, "game quote carries no intro price");
  const cap = await cp.customPlanCapacityCheck(spec);
  must(cap.ok, `game capacity: ${cap.reason}`);
  const previewFirstTerm = await firstTermMonthly(q.priceCents, q.introPriceCents!, term);

  const made = await cp.createCustomGamePlan({ spec, gameFamily: family, players: 150 });
  created.planIds.push(made.plan.id);
  created.gamePlanIds.push(made.gamePlanId);
  const gp = await db.gamePlan.findUniqueOrThrow({ where: { id: made.gamePlanId } });
  must(gp.priceCents === q.priceCents, `created tier ${gp.priceCents} != quoted ${q.priceCents}`);
  must(gp.introPriceCents === q.introPriceCents, `created tier intro ${gp.introPriceCents} != quoted ${q.introPriceCents}`);

  const user = await makeUser("game");
  const intent = {
    gamePlanId: gp.id, termMonths: term, serverName: "Verify intro", hostname: "",
    subdomain: `vi${ts}`, config: {} as Record<string, string | number | boolean>,
  };
  const gq = await gameOrderQuote(intent as never, { userId: user.id });
  const pct = await annualDiscountPct();
  const expectCharge = vpsTermPriceCents(q.priceCents, term, pct)
    - introFirstTermDiscountCents(q.priceCents, q.introPriceCents!, term, null, pct);
  must(gq.chargeCents === expectCharge, `gameOrderQuote charge ${gq.chargeCents} != expected ${expectCharge}`);
  must(Math.round(gq.chargeCents / term) === previewFirstTerm, `wizard first-term/mo ${previewFirstTerm} != charge/term ${gq.chargeCents / term}`);
  must(gq.renewalTotalCents === vpsTermPriceCents(q.priceCents, term, pct), "game renewal total != regular annual");

  const pi = await chargeCard(user, gq.chargeCents, `custom ${family} ${gp.name}`);
  const serverId = await placeGameOrder(user, intent as never, {
    chargeCents: gq.chargeCents, couponDiscountCents: gq.couponDiscountCents, couponLabel: gq.couponLabel,
  } as never);
  created.serverIds.push(serverId);
  const s = await db.server.findUniqueOrThrow({ where: { id: serverId }, include: { plan: true, gamePlan: true } });
  const u2 = await db.user.findUniqueOrThrow({ where: { id: user.id } });
  const renewal = renewalCharge(s as never, await currentRenewalPrices());
  must((s as any).grandfatheredRenewalCents === q.priceCents, `game grandfathered ${(s as any).grandfatheredRenewalCents} != ${q.priceCents}`);
  must(renewal.netCents === vpsTermPriceCents(q.priceCents, term, pct), `game renewal ${renewal.netCents}`);
  must(u2.balanceCents === 0, `game wallet should net to 0, is ${u2.balanceCents}`);
  results.push({
    case: `${family} ${spec.cpuCores} vCPU / ${spec.ramMB / 1024} GB / ${spec.diskGB} GB, annual (${pct}% annual discount)`,
    regularMonthly: $(q.priceCents),
    introQuoted: $(q.introPriceCents!),
    wizardFirstTermMonthly: $(previewFirstTerm),
    createdGamePlanRow: `${$(gp.priceCents)} / intro ${$(gp.introPriceCents!)}`,
    gameOrderQuoteCharge: `${$(gq.chargeCents)} for 12 months`,
    stripe: `${pi.id} ${pi.status} ${$(pi.amount_received)}`,
    termPromoPercent: s.termPromoPercent,
    grandfatheredRenewal: $((s as any).grandfatheredRenewalCents),
    renewalCharge: `${$(renewal.totalCents)} every ${renewal.months} mo`,
  });
}

console.log(JSON.stringify(results, null, 2));

// ─── cleanup: the rows this script made (users + invoices kept as a record) ──
for (const id of created.serverIds) {
  await db.job.deleteMany({ where: { serverId: id } });
  await db.server.delete({ where: { id } });
}
await db.gamePlan.deleteMany({ where: { id: { in: created.gamePlanIds } } });
await db.plan.deleteMany({ where: { id: { in: created.planIds } } });
console.log(`[verify] cleaned up ${created.serverIds.length} servers + jobs, ${created.gamePlanIds.length} game plans, ${created.planIds.length} plans`);
await db.$disconnect();

