// Staging walkthrough of the custom builder: intro price in the live preview
// (VPS + game), the Review step, and the capacity-exceeded -> sales ticket flow.
// Usage: node shots.cjs <mode: vps|game|sales> <outdir> [family]
const { chromium } = require("/opt/nxeon/node_modules/playwright");

const BASE = "https://staging.nxeon.cloud";
const [mode, out, family = "rust"] = process.argv.slice(2);

async function setRange(page, label, value) {
  const el = page.locator(`input[type=range][aria-label="${label}"]`);
  await el.evaluate((node, v) => {
    const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value").set;
    setter.call(node, String(v));
    node.dispatchEvent(new Event("input", { bubbles: true }));
    node.dispatchEvent(new Event("change", { bubbles: true }));
  }, value);
}

async function text(page, sel) {
  return (await page.locator(sel).first().innerText()).replace(/\s+/g, " ").trim();
}

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
  page.on("pageerror", (e) => console.log("PAGEERROR", e.message));
  const email = `custom-intro-${mode}-${Date.now()}@nxeon-internal.test`;

  await page.goto(`${BASE}/register`, { waitUntil: "load", timeout: 60000 });
  await page.waitForTimeout(1500);
  await page.fill("#register-name", "Custom Intro Test");
  await page.fill("#register-email", email);
  await page.fill("#register-password", "CustomIntroTest123!");
  await page.click('button:has-text("Create account")', { force: true });
  await page.waitForURL(/dashboard/, { timeout: 60000 }).catch(() => {});
  console.log("registered", email, "->", page.url());

  const svc = mode === "vps" || mode === "sales" ? "vps" : "game";
  await page.goto(`${BASE}/dashboard/deploy`, { waitUntil: "load", timeout: 60000 });
  await page.waitForTimeout(2500);

  if (svc === "vps") {
    // Service tile, then the Custom tile.
    await page.locator("button:has-text('VPS')").first().click().catch(() => {});
    await page.waitForTimeout(1500);
  } else {
    await page.locator("button:has-text('Game')").first().click().catch(() => {});
    await page.waitForTimeout(1500);
    const search = page.locator('input[placeholder*="Search" i]').first();
    if (await search.count()) { await search.fill(family === "rust" ? "Rust" : family); await page.waitForTimeout(800); }
    await page.locator(`button:has-text("${family === "rust" ? "Rust" : family}")`).first().click();
    await page.waitForTimeout(1500);
  }
  const tile = page.locator("button:has-text('Build your own')").first();
  await tile.scrollIntoViewIfNeeded();
  await page.screenshot({ path: `${out}/${mode}-1-tile.png`, fullPage: false });
  console.log("TILE:", (await tile.innerText()).replace(/\s+/g, " "));
  await tile.click();
  await page.waitForSelector("#custom-builder", { timeout: 15000 });

  if (mode === "sales") {
    // Max RAM: 128 GB exceeds every staging node's ceiling -> capacity-exceeded.
    await setRange(page, "Memory (GB)", 128);
  }
  // Let the 450 ms debounced authoritative quote land.
  await page.waitForTimeout(3500);
  const builder = page.locator("#custom-builder");
  await builder.scrollIntoViewIfNeeded();
  await builder.screenshot({ path: `${out}/${mode}-2-builder.png` });
  console.log("BUILDER:", await text(page, "#custom-builder"));

  if (mode === "sales") {
    await page.locator("#custom-builder button:has-text('Request this build')").first().click();
    await page.waitForTimeout(800);
    await page.locator("#custom-builder textarea").fill("Verification ticket from the staging walkthrough. Need this for a 24/7 build server, Singapore preferred.");
    await builder.screenshot({ path: `${out}/${mode}-3-request-form.png` });
    await page.locator("#custom-builder button:has-text('Send to our team')").click();
    await page.waitForURL(/support/, { timeout: 30000 });
    await page.waitForTimeout(3000);
    console.log("AFTER SEND URL:", page.url());
    await page.screenshot({ path: `${out}/${mode}-4-ticket.png`, fullPage: false });
    console.log("EMAIL:", email);
    await browser.close();
    return;
  }

  // Build it, then walk to the Review step for the summary.
  await page.locator("#custom-builder button:has-text('Use this custom server')").click();
  await page.waitForTimeout(3000);
  const tile2 = page.locator("button:has-text('Build your own')").first();
  await tile2.scrollIntoViewIfNeeded().catch(() => {});
  await page.screenshot({ path: `${out}/${mode}-3-after-build.png`, fullPage: false });
  console.log("BUILT TILE:", (await tile2.innerText().catch(() => "")).replace(/\s+/g, " "));
  console.log("EMAIL:", email);
  await browser.close();
})().catch((e) => { console.error("FAILED", e); process.exit(1); });

